CREATE TABLE IF NOT EXISTS users (id varchar(36) PRIMARY KEY, username varchar(64) UNIQUE NOT NULL, password_hash varchar(128) NOT NULL, role varchar(16) NOT NULL CHECK(role IN ('admin','operator','viewer')), created_at datetime(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS sessions (token_hash varchar(64) PRIMARY KEY, user_id varchar(36) NOT NULL, expires_at datetime(6) NOT NULL, FOREIGN KEY(user_id) REFERENCES users(id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS login_attempts (bucket_key varchar(64) PRIMARY KEY, attempts integer NOT NULL, window_start datetime(6) NOT NULL) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS servers (id varchar(36) PRIMARY KEY, name varchar(128) NOT NULL, hostname varchar(253) NOT NULL DEFAULT '', distribution varchar(128) NOT NULL DEFAULT '', group_name varchar(64) NOT NULL DEFAULT '', notes varchar(1024) NOT NULL DEFAULT '', agent_version varchar(32) NOT NULL DEFAULT '', revoked boolean NOT NULL DEFAULT false, last_seen_at datetime(6), created_at datetime(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS agent_enrollments (token_hash varchar(64) PRIMARY KEY, server_id varchar(36) NOT NULL, expires_at datetime(6) NOT NULL, used_at datetime(6), FOREIGN KEY(server_id) REFERENCES servers(id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS agent_credentials (token_hash varchar(64) PRIMARY KEY, server_id varchar(36) NOT NULL, created_at datetime(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6), revoked_at datetime(6), FOREIGN KEY(server_id) REFERENCES servers(id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS audit_logs (id bigint AUTO_INCREMENT PRIMARY KEY, actor_id varchar(36), action varchar(64) NOT NULL, target varchar(128) NOT NULL, created_at datetime(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6), FOREIGN KEY(actor_id) REFERENCES users(id), INDEX audit_time(created_at)) ENGINE=InnoDB;
